"""Demo: meaning-density bound vs. exact enumeration."""
from __future__ import annotations
from fractions import Fraction
from itertools import product
from typing import Tuple

def meaning_density_bound(A: int, L: int, m: int) -> Fraction:
    """Union bound (L - m + 1) * A^{-m}; prefactor is the placement count."""
    return Fraction(L - m + 1, A ** m)

def exact_meaning_density(A: int, L: int, passage: Tuple[int, ...]) -> Fraction:
    """True fraction of volumes containing `passage` as a contiguous block."""
    m = len(passage)
    count = 0
    for v in product(range(A), repeat=L):
        if any(v[i:i+m] == passage for i in range(L - m + 1)):
            count += 1
    return Fraction(count, A ** L)

if __name__ == "__main__":
    for L in (4, 6, 8):
        b = meaning_density_bound(4, L, 2)
        t = exact_meaning_density(4, L, (1, 2))
        print(f"L={L}: bound={float(b):.5f} true={float(t):.5f} ok={t<=b}")

"""Demo: build and verify optimal de Bruijn code tours."""
from __future__ import annotations
from itertools import product
from typing import Dict, List, Tuple

def de_bruijn_sequence(A: int, k: int) -> List[int]:
    """Linear expansion (length A^k + k - 1) of an order-k de Bruijn sequence."""
    graph: Dict[Tuple[int, ...], List[int]] = {
        v: list(range(A)) for v in product(range(A), repeat=k - 1)
    }
    stack: List[Tuple[int, ...]] = [tuple([0] * (k - 1))]
    path: List[int] = []
    circuit: List[int] = []
    while stack:
        v = stack[-1]
        if graph[v]:
            s = graph[v].pop()
            stack.append(v[1:] + (s,))
            path.append(s)
        else:
            stack.pop()
            if path:
                circuit.append(path.pop())
    circuit.reverse()
    return circuit + circuit[: k - 1]

def verify(seq: List[int], A: int, k: int) -> bool:
    """Every length-k code appears exactly once."""
    blocks = [tuple(seq[i:i+k]) for i in range(len(seq) - k + 1)]
    return sorted(blocks) == sorted(product(range(A), repeat=k))

if __name__ == "__main__":
    for A, k in [(4, 2), (2, 3), (3, 3)]:
        s = de_bruijn_sequence(A, k)
        print(f"A={A} k={k}: len={len(s)} (=A^k+k-1={A**k+k-1}) ok={verify(s,A,k)}")

