function DE_BRUIJN_TOUR(A, k):
    graph <- {v: [0..A-1] for v in all (k-1)-codes}
    stack <- [(0,...,0)]; path <- []; circuit <- []
    while stack not empty:
        v <- top(stack)
        if graph[v] not empty:
            s <- pop an out-symbol of v
            push v[1:]+(s) onto stack; append s to path
        else:
            pop stack; move last path symbol to circuit
    reverse circuit
    return circuit + circuit[0 : k-1]

function CATALOG_THRESHOLDS(A, L):
    pop <- A^L
    no_self_catalog <- (pop >= 1)    # A^L < 2^(A^L)
    min_distributed <- pop           # N >= A^L
    return {pop, no_self_catalog, min_distributed}
